import{_ as a,C as o,o as i,c as r,a2 as s,b as c,w as t,a as l,E as d,a3 as h}from"./chunks/framework.XaTYfhfj.js";const b=JSON.parse('{"title":"14.8 Consistency, Concurrency & Distributed State","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.8-consistency-and-concurrency.md","filePath":"system-design/14.8-consistency-and-concurrency.md"}'),p={name:"system-design/14.8-consistency-and-concurrency.md"};function u(k,e,y,g,m,C){const n=o("Mermaid");return i(),r("div",null,[e[1]||(e[1]=s('<h1 id="_14-8-consistency-concurrency-distributed-state" tabindex="-1">14.8 Consistency, Concurrency &amp; Distributed State <a class="header-anchor" href="#_14-8-consistency-concurrency-distributed-state" aria-label="Permalink to &quot;14.8 Consistency, Concurrency &amp; Distributed State&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Consistency models define how and when updates to data become visible across all nodes and users in a distributed system. Concurrency control prevents race conditions when multiple users or processes attempt to modify the same resource simultaneously.</p><hr><h2 id="_2-consistency-models-applied-in-truthguard" tabindex="-1">2. Consistency Models Applied in TruthGuard <a class="header-anchor" href="#_2-consistency-models-applied-in-truthguard" aria-label="Permalink to &quot;2. Consistency Models Applied in TruthGuard&quot;">​</a></h2>',5)),(i(),c(h,null,{default:t(()=>[d(n,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20StrongConsistency%20%5B%22Strong%20Consistency%20(ACID)%22%5D%0A%20%20%20%20%20%20%20%20AuthRole%5B%22User%20Role%20%26%20Permissions%20(profiles%20table)%22%5D%0A%20%20%20%20%20%20%20%20AuditLog%5B%22Chain%20of%20Custody%20Logs%20(activityLog)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20EventualConsistency%20%5B%22Eventual%20Consistency%20(BASE)%22%5D%0A%20%20%20%20%20%20%20%20ExtGrounding%5B%22Fact-Checking%20Syndications%20(PolitiFact%20%2F%20Snopes)%22%5D%0A%20%20%20%20%20%20%20%20AnalyticsRollup%5B%22SOC%20Threat%20Metrics%20%26%20Dashboard%20Stats%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20StrongConsistency%20--%3E%20Enforcement1%5B%22PostgreSQL%20Serializable%20%2F%20Repeatable%20Read%22%5D%0A%20%20%20%20EventualConsistency%20--%3E%20Enforcement2%5B%22Background%20Cron%20Ingestion%20%26%20Read%20Caches%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s(`<ol><li><strong>Strong Consistency for Audit Custody &amp; Profiles</strong>: <ul><li>Updates to user permissions (<code>Journalist</code> -&gt; <code>Analyst</code>) and evidence custody actions must be immediately consistent across all transactions. PostgreSQL transactions with ACID guarantees prevent dirty reads.</li></ul></li><li><strong>Eventual Consistency for External Fact-Checking</strong>: <ul><li>Fact-checking syndications (Snopes, PolitiFact) update periodically. A 5-minute replication delay between external fact-checker releases and local cache population is fully acceptable for threat telemetry.</li></ul></li></ol><hr><h2 id="_3-concurrency-control-race-condition-defenses" tabindex="-1">3. Concurrency Control &amp; Race Condition Defenses <a class="header-anchor" href="#_3-concurrency-control-race-condition-defenses" aria-label="Permalink to &quot;3. Concurrency Control &amp; Race Condition Defenses&quot;">​</a></h2><h3 id="optimistic-concurrency-control-occ" tabindex="-1">Optimistic Concurrency Control (OCC) <a class="header-anchor" href="#optimistic-concurrency-control-occ" aria-label="Permalink to &quot;Optimistic Concurrency Control (OCC)&quot;">​</a></h3><p>For multi-analyst case editing, TruthGuard employs optimistic locking using an <code>updated_at</code> timestamp column:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">incidents</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;investigating&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, updated_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> now</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> updated_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :last_seen_timestamp;</span></span></code></pre></div><p>If another analyst modified the case record concurrently, the update count returns 0, prompting the user with a conflict resolution modal rather than silently overwriting evidence notes.</p><h3 id="distributed-locking-for-file-deduplication" tabindex="-1">Distributed Locking for File Deduplication <a class="header-anchor" href="#distributed-locking-for-file-deduplication" aria-label="Permalink to &quot;Distributed Locking for File Deduplication&quot;">​</a></h3><p>When parallel ingest streams submit identical video files, a distributed Redis lock (<code>SET lock:hash:&lt;sha256&gt; true NX EX 30</code>) ensures only one worker initiates GPU processing, while sibling requests block until the lock releases.</p><hr><h2 id="_4-30-second-spoken-interview-answer" tabindex="-1">4. 30-Second Spoken Interview Answer <a class="header-anchor" href="#_4-30-second-spoken-interview-answer" aria-label="Permalink to &quot;4. 30-Second Spoken Interview Answer&quot;">​</a></h2><blockquote><p>&quot;We apply a hybrid consistency model tailored to forensic data requirements: strong consistency in PostgreSQL for user authorization and custody audit trails, and eventual consistency for external fact-check feed synchronizations.</p><p>To prevent race conditions during concurrent case investigations, we use optimistic concurrency control with timestamp checks, paired with distributed Redis locks to prevent duplicate GPU processing on identical file hashes.&quot;</p></blockquote>`,12))])}const f=a(p,[["render",u]]);export{b as __pageData,f as default};
